# Confirmatory corpus 2: 30 public incidents not used by v1/v2/holdout.
#
# Each incident contributes exactly one stored case. Five evaluation queries
# (2 literal, 2 paraphrase, 1 semantic) target that same case, so a correct
# retrieval is never mislabeled because a same-incident sibling outranked it.
# Source summaries are from the public list maintained by danluu/post-mortems;
# the original incident URL is stored with every case.
param(
    [string]$MemDir = (Join-Path $PSScriptRoot "confirm2-mem"),
    [string]$Csv = (Join-Path $PSScriptRoot "confirm2-cases.csv"),
    [string]$Binary = (Join-Path $PSScriptRoot "..\rs\target\release\scx.exe"),
    [switch]$Force
)

$ErrorActionPreference = "Stop"

function Write-Utf8([string]$Path, [string]$Text) {
    [IO.File]::WriteAllText($Path, $Text, (New-Object Text.UTF8Encoding $false))
}
function CsvField([string]$Value) { return '"' + $Value.Replace('"', '""') + '"' }

if (-not (Test-Path -LiteralPath $Binary)) { throw "missing release binary: $Binary" }
if (-not (Test-Path -LiteralPath $MemDir)) { New-Item -ItemType Directory -Force -Path $MemDir | Out-Null }
$existing = @(Get-ChildItem -LiteralPath $MemDir -Force -ErrorAction SilentlyContinue)
if ($existing.Count -gt 0) {
    if (-not $Force) { throw "MemDir is not empty: $MemDir (use -Force to clear workspace-local dir)" }
    $wsRoot = (Resolve-Path -LiteralPath (Join-Path $PSScriptRoot "..")).Path
    $memAbs = (Resolve-Path -LiteralPath $MemDir).Path
    if (-not $memAbs.StartsWith($wsRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
        throw "refusing to clear non-workspace dir: $memAbs"
    }
    Remove-Item -LiteralPath $memAbs -Recurse -Force
    New-Item -ItemType Directory -Force -Path $memAbs | Out-Null
}

$incidents = @(
    @{ id="cf20200717"; src="https://web.archive.org/web/20211016040522/https://blog.cloudflare.com/cloudflare-outage-on-july-17-2020/"; sym="atlanta datacenter traffic crush"; key="backbone typo sent europe traffic to one site"; pa="a configuration typo during backbone maintenance forced all american and european traffic into atlanta"; pb="engineers found a single datacenter taking the full cross region load"; se="骨干网维护时配置打错一个字符，欧美流量全灌进亚特兰大数据中心导致压垮"; rc="A typo in the Atlanta datacenter network configuration during private backbone maintenance sent all traffic from America and Europe to that one datacenter and crushed it. 中文根因：骨干网维护配置打错，欧美流量集中到亚特兰大单点"; fix="修正骨干网配置并恢复流量分流" },
    @{ id="cf20221025"; src="https://web.archive.org/web/20221112015610/https://blog.cloudflare.com/partial-cloudflare-outage-on-october-25-2022/"; sym="tiered cache 530 responses"; key="cache change failed five percent requests"; pa="a tiered cache update caused status 530 responses for almost six hours"; pb="tests missed a cache deployment that failed about five percent of requests"; se="分层缓存改动上线后部分用户持续收到 530 错误近六小时"; rc="A change to the Tiered Cache system caused requests to fail with status 530 for almost six hours; a test blind spot missed it. 中文根因：分层缓存改动存在测试盲区，导致部分请求返回 530"; fix="回滚缓存改动并补充覆盖真实流量的测试" },
    @{ id="cf20231030"; src="https://blog.cloudflare.com/cloudflare-incident-on-october-30-2023/"; sym="staging build served in production"; key="deploy tool routed traffic to unauthorized endpoint"; pa="a deployment bug made production use a staging build and return 401"; pb="workers kv pages access and turnstile failed after traffic hit the wrong endpoint"; se="部署工具把生产环境指到 staging 构建，流量打到未授权端点后大面积 401"; rc="A deployment tool bug made production reference a staging build, routing traffic to an unauthorized endpoint that returned HTTP 401 errors and cascaded across Workers KV, Pages, Access, and Turnstile. 中文根因：部署工具引用 staging 构建，生产流量进入未授权端点"; fix="回滚部署映射并恢复正确生产构建" },
    @{ id="googlegclb"; src="https://status.cloud.google.com/incidents/6PM5mNd43NbMqjCZ5REh"; sym="gclb 404 latent config bug"; key="load balancing network config service bug"; pa="a hidden network configuration bug caused google cloud load balancing to return 404"; pb="routine system activity triggered the flawed config service and broke downstream websites"; se="负载均衡配置服务里的潜在缺陷被例行操作触发，网站返回 404"; rc="A latent bug in a network configuration service was triggered during routine system operation, causing Google Cloud Load Balancing to return 404 errors for downstream services. 中文根因：网络配置服务存在潜在缺陷，例行操作触发后返回 404"; fix="回滚配置服务变更并修复潜在缺陷" },
    @{ id="valvebgp"; src="https://blog.thousandeyes.com/steam-outage-monitor-data-center-connectivity/"; sym="steam bgp route severed"; key="bad bgp config cut level3 telia zayo"; pa="an incorrect border gateway protocol configuration isolated steam from three upstream networks"; pb="steam became unreachable worldwide after its routes were withdrawn"; se="BGP 配置错误切断了 Valve 到三家运营商的路由，Steam 全球不可达"; rc="A bad BGP configuration severed Valve connectivity to Level 3, Telia, and Abovenet/Zayo and caused a global Steam outage. 中文根因：错误 BGP 配置切断 Steam 与三家上游运营商连接"; fix="修正 BGP 路由并恢复上游连接" },
    @{ id="aws2329b7"; src="https://aws.amazon.com/message/2329B7/"; sym="eu west transformer plc generator failure"; key="backup generators failed phase check"; pa="a transformer fault and a broken phase check stopped backup power in eu west"; pb="ec2 ebs and rds were disrupted because the generators never came online"; se="EU West 变压器故障且发电机相位检查失效，备用电源没能启动"; rc="A transformer failed and a PLC that checks generator phase failed too, preventing backup generators from coming online and affecting EC2, EBS, and RDS in EU West. 中文根因：变压器与发电机相位检查同时故障，备用电源无法启动"; fix="恢复变压器和发电机，修复相位检查冗余" },
    @{ id="aws4372t8"; src="https://aws.amazon.com/message/4372T8/"; sym="sydney storm power loss availability zone"; key="isolation breakers failed backup reserves drained"; pa="severe weather cut utility power in sydney and the breakers did not isolate the fault"; pb="backup energy drained into the damaged grid and many instances went down"; se="悉尼恶劣天气断电，隔离断路器未动作，备用电能倒灌后大量实例中断"; rc="Severe weather caused utility power loss at an AWS Sydney facility; power isolation breakers did not engage and backup energy drained into the degraded grid, disrupting many instances. 中文根因：悉尼恶劣天气断电，隔离断路器未动作导致备用电能耗尽"; fix="恢复供电并修复断路器隔离逻辑" },
    @{ id="aws656481"; src="https://aws.amazon.com/message/656481/"; sym="sao paulo generator failure invalid route"; key="automated power control malfunction manual generators"; pa="two generators failed during a sao paulo power outage and the control system had to be bypassed"; pb="after power returned a bad route advertisement degraded both availability zones"; se="圣保罗断电时两台发电机接连故障，恢复后错误路由又影响两个可用区"; rc="Utility power was lost in a Sao Paulo AZ; two generators failed, the automated power control malfunctioned, and after recovery a bad route advertisement degraded both zones. 中文根因：圣保罗断电叠加发电机故障和错误路由通告"; fix="手工恢复发电机并修正路由配置" },
    @{ id="arpanet1980"; src="https://datatracker.ietf.org/doc/html/rfc789.html"; sym="arpanet imp corrupt routing checksum"; key="bad sequence numbers filled buffers"; pa="a faulty interface processor spread corrupted routing data even though checksums looked valid"; pb="buffers filled and nodes removed themselves after keepalives were lost"; se="接口处理机损坏后错误路由数据仍带着正确校验和扩散，节点因保活丢失退出网络"; rc="A malfunctioning IMP corrupted routing data; software recomputed checksums that looked valid, sequence numbers filled buffers, and nodes removed themselves from the network. 中文根因：IMP 损坏导致错误路由扩散、缓冲区耗尽和节点退出"; fix="重启故障 IMP 并修正路由与序号处理" },
    @{ id="cfbyzantine"; src="https://web.archive.org/web/20211015231917/https://blog.cloudflare.com/a-byzantine-failure-in-the-real-world/"; sym="switch byzantine failure api dashboard"; key="partial switch misbehavior cascade six hours"; pa="a partially faulty switch caused a cascading failure across the api and dashboard"; pb="the control plane stayed degraded for more than six hours because of the switch"; se="交换机局部异常引发级联故障，API 和控制台中断六小时多"; rc="A partially misbehaving switch caused a cascading Byzantine failure that impacted API and dashboard availability for six hours and 33 minutes. 中文根因：交换机部分异常引发拜占庭式级联故障"; fix="隔离并更换异常交换机，恢复控制面" },
    @{ id="cfportland"; src="https://blog.cloudflare.com/major-data-center-power-failure-again-cloudflare-code-orange-tested/"; sym="portland breaker coordination total power loss"; key="cascade safety breakers bypassed redundancy"; pa="incorrect breaker coordination settings took out every power path in portland"; pb="the data center lost all redundant power because the cascade breakers tripped together"; se="波特兰机房断路器协调参数错误，所有冗余供电路径同时失效"; rc="Incorrectly set breaker coordination settings in the Portland data center caused a complete power loss that bypassed all redundant power paths. 中文根因：波特兰机房断路器协调参数错误，冗余供电路径全部失效"; fix="修正断路器协调设置并验证冗余切换" },
    @{ id="google15056"; src="https://status.cloud.google.com/incident/compute/15056#5719570367119360"; sym="lightning persistent disk io errors"; key="compute engine storage lost power data loss"; pa="lightning strikes knocked out storage power and some persistent disks returned io errors"; pb="a small number of standard hdd volumes lost data permanently"; se="欧洲机房遭雷击后存储断电，部分持久盘出现 IO 错误并永久丢数据"; rc="Lightning strikes caused power loss to Compute Engine storage in europe-west1-b; a subset of Standard Persistent Disks had I/O errors and a small fraction suffered permanent data loss. 中文根因：雷击导致欧洲存储断电，部分持久盘 IO 错误并丢数据"; fix="恢复存储供电并恢复受影响磁盘" },
    @{ id="googlecooling"; src="https://status.cloud.google.com/incidents/fmEL9i2fArADKawkZAa2"; sym="europe west2 cooling failure unavailable"; key="multiple redundant cooling systems failed together"; pa="several supposedly redundant cooling units failed at once in one zone"; pb="customers could not use multiple cloud products while the data center overheated"; se="同一可用区的多套冗余制冷系统同时失效，多个云服务不可用"; rc="Multiple redundant cooling systems failed simultaneously in a data center hosting europe-west2-a, causing service unavailability for several Google Cloud products. 中文根因：冗余制冷系统同时失效，机房过热导致服务不可用"; fix="恢复制冷并增加独立冗余" },
    @{ id="pythonanywhere189"; src="https://blog.pythonanywhere.com/189/"; sym="storage volume failure hosted sites"; key="volume outage spread to user programs"; pa="a failed storage volume took down the main site and customer web applications"; pb="the fault spread to other hosted sites that depended on the same disk"; se="存储卷故障导致主站和用户程序中断，并扩散到其他托管站点"; rc="A storage volume failure caused outages for the PythonAnywhere site, user programs and websites dependent on that volume, and later spread to other hosted sites. 中文根因：存储卷故障影响主站和依赖该卷的用户站点"; fix="更换故障存储卷并迁移受影响站点" },
    @{ id="aws101925"; src="https://aws.amazon.com/message/101925/"; sym="dynamodb dns enactor race empty endpoint"; key="stale plan deleted regional record"; pa="two dns enactor processes raced and one removed the regional dynamodb endpoint"; pb="the missing record cascaded into ec2 load balancers and lambda for many hours"; se="两个 DNS Enactor 竞争，旧计划覆盖并删掉 DynamoDB 区域端点，故障级联十余小时"; rc="A race between two DNS Enactor processes left the regional DynamoDB endpoint empty; a stale plan overwrote it and cleanup deleted the record, cascading into EC2, load balancers, and Lambda. 中文根因：DNS Enactor 竞态导致区域端点被旧计划覆盖并删除"; fix="修复 DNS Enactor 并发控制并恢复端点" },
    @{ id="githubmlag"; src="https://github.blog/news-insights/the-library/downtime-last-saturday/"; sym="mlag failover stonith fileservers"; key="switch upgrade froze network ninety seconds"; pa="an aggregation switch upgrade briefly froze the network and tripped pacemaker heartbeats"; pb="fileserver pairs fenced each other and both nodes stayed powered off"; se="交换机升级让网络短暂冻结，文件服务器心跳超时后互相 STONITH 关机"; rc="During an aggregation switch ISSU upgrade, an MLAG failover briefly froze the network, causing fileserver Pacemaker pairs to exceed heartbeats and STONITH each other. 中文根因：交换机升级触发 MLAG 异常，文件服务器心跳超时后互相关机"; fix="修复 ISSU 流程并恢复文件服务器节点" },
    @{ id="githubzk"; src="https://github.blog/news-insights/company-news/github-availability-report-october-2020/"; sym="zookeeper two leaders kafka split"; key="replacement hosts elected second leader"; pa="too many replacement zookeeper hosts created a second cluster and leader"; pb="two kafka controllers served conflicting state and background jobs failed"; se="ZooKeeper 替换主机过快选出双主，Kafka 也出现两个控制器导致后台任务写入失败"; rc="Too many replacement ZooKeeper hosts were added during reprovisioning, creating two clusters and two leaders; Kafka then had two controllers and about ten percent of background-job writes failed. 中文根因：ZooKeeper 替换过快形成双主，Kafka 双控制器导致写入失败"; fix="收敛 ZooKeeper 集群并修复 Kafka 控制器选举" },
    @{ id="gocardlesspg"; src="https://gocardless.com/blog/zero-downtime-postgres-migrations-the-hard-parts/"; sym="postgres migration blocked queries"; key="fast migration met long read query"; pa="a quick schema migration collided with a long running read and locked a critical table"; pb="all queries to the table stalled for fifteen seconds"; se="快速数据库迁移撞上长读查询，关键表被锁十五秒"; rc="A fast PostgreSQL migration combined with a long-running read query and blocked all queries on a critical table for about fifteen seconds. 中文根因：快速迁移与长读查询叠加，关键表被锁"; fix="调整迁移锁策略并重试" },
    @{ id="google17003"; src="https://status.cloud.google.com/incident/compute/17003#5660850647990272"; sym="load balancer slow code path frozen addressing"; key="rarely changed balancer took two hours"; pa="many changes to a rarely touched load balancer went through a very slow path"; pb="public address changes were stuck for about two hours"; se="很少改动的负载均衡器走了极慢代码路径，公网地址变更冻结两小时"; rc="Many changes to a rarely modified load balancer were applied through a very slow code path, freezing all public addressing changes for about two hours. 中文根因：负载均衡器变更走慢代码路径，公网地址变更冻结"; fix="修复慢路径并恢复地址变更" },
    @{ id="googlefiber"; src="https://status.cloud.google.com/incidents/eo76pxZiDgWVz4z3kmUv"; sym="backbone fiber component packet loss"; key="bandwidth dropped between gateway and edge"; pa="a failed component on a backbone fiber path reduced capacity and caused packet loss"; pb="traffic moved to remaining links but the gateway and edge locations still dropped packets"; se="骨干光纤路径组件故障导致网关到边缘节点带宽下降并丢包"; rc="A component failure on a backbone fiber path reduced bandwidth between a central US gateway and multiple edge locations, causing packet loss while traffic moved to remaining paths. 中文根因：骨干光纤组件故障导致带宽下降和丢包"; fix="更换故障组件并恢复骨干容量" },
    @{ id="incidentio32"; src="https://incident.io/blog/one-two-skip-a-few"; sym="postgres sequence jump 32"; key="failover promoted follower nextval cache"; pa="a postgres high availability promotion left the incident id sequence advanced by thirty two"; pb="the follower skipped cached sequence values when it became primary"; se="Postgres 高可用切换后新主库跳过预分配序列值，事件编号直接跳 32"; rc="After a Postgres HA promotion, the sequence advanced by up to 32 because nextval pre-allocates values on the WAL and the follower saw the post-crash state. 中文根因：故障切换后序列预分配值被跳过，事件编号跳变"; fix="改用基于最大值的编号触发器" },
    @{ id="azureleap"; src="https://azure.microsoft.com/en-us/blog/summary-of-windows-azure-service-disruption-on-feb-29th-2012/"; sym="leap day certificate expired invalid date"; key="one year computed as date plus year"; pa="certificate code added one calendar year and generated an invalid february date"; pb="the bad expiry made azure reject certificates and caused a day long outage"; se="证书有效期直接用日期加一年，闰日生成非法过期时间，Azure 大面积拒绝证书"; rc="Certificate code computed one year as the current date plus one year; on leap day this produced February 29 of the next year, an invalid date that caused a global Azure outage. 中文根因：证书有效期计算在闰日生成非法日期"; fix="修复日期计算并重新签发证书" },
    @{ id="cfleap"; src="https://web.archive.org/web/20211104160742/https://blog.cloudflare.com/how-and-why-the-leap-second-affected-cloudflare-dns/"; sym="leap second rrdns panic cname"; key="negative rand int63n after time moved backward"; pa="a leap second made time appear to run backward and the dns selector panicked"; pb="some cname lookups failed because a negative random bound was passed to go"; se="闰秒让时间回退，DNS 轮询选择器把负数传给随机函数后 panic"; rc="The leap second made time move backward; RRDNS assumed Go time was monotonic and passed a negative value to rand.Int63n, causing panics on some CNAME lookups. 中文根因：闰秒导致时间回退，DNS 轮询使用负数随机边界"; fix="修复时间单调性假设并发布补丁" },
    @{ id="linuxleap"; src="https://web.archive.org/web/20220427012208/https://lkml.org/lkml/2009/1/2/373"; sym="leap second printk xtime deadlock"; key="timer interrupt held lock while logging"; pa="leap second code logged from the timer interrupt and deadlocked on the time lock"; pb="klogd tried to read the clock while printk already held xtime lock"; se="闰秒处理在定时器中断里 printk，klogd 再取时间锁造成死锁"; rc="Leap second code ran in the timer interrupt while holding xtime_lock; its printk woke klogd, which tried to read the clock and deadlocked on the same lock. 中文根因：定时器中断持锁 printk，klogd 再次取时间锁死锁"; fix="调整闰秒日志路径避免持锁唤醒" },
    @{ id="awselb"; src="https://aws.amazon.com/message/680587/"; sym="elb maintenance production state data"; key="maintenance process ran against live balancer state"; pa="a maintenance job was accidentally pointed at production elastic load balancer state"; pb="the live load balancer data was modified by an unintended process"; se="维护进程误对生产 ELB 状态数据执行，负载均衡服务异常"; rc="A maintenance process was inadvertently run against production Elastic Load Balancer state data, causing the load balancer to fail. 中文根因：维护进程误操作生产 ELB 状态数据"; fix="限制维护脚本作用域并恢复状态" },
    @{ id="awsmetadata"; src="https://aws.amazon.com/message/5467D2/"; sym="metadata timeout storage nodes retry storm"; key="network disruption pushed response above timeout"; pa="a network problem slowed metadata calls past their timeout and storage nodes removed themselves"; pb="the removed nodes kept retrying and kept the metadata service overloaded"; se="网络异常让元数据响应超过超时，存储节点自摘后不断重试形成风暴"; rc="A network disruption overloaded metadata services, responses exceeded timeouts, storage nodes removed themselves, and their retries kept the metadata load high. 中文根因：网络异常导致元数据超时，存储节点自摘并重试形成风暴"; fix="提高超时并抑制重试风暴" },
    @{ id="awskinesis11201"; src="https://aws.amazon.com/message/11201/"; sym="kinesis frontend cache thread limit"; key="operating system thread cap hit during scale"; pa="scaling the kinesis cache fleet hit an operating system thread limit"; pb="cognito lambda and cloudwatch degraded after the frontend servers ran out of threads"; se="Kinesis 前端缓存扩容撞到系统线程上限，多个下游服务受影响"; rc="Scaling the Kinesis front-end cache fleet pushed every server past the operating system thread limit, affecting Cognito, Lambda, CloudWatch and other downstream services. 中文根因：Kinesis 前端扩容超过系统线程上限"; fix="调整线程配置并重新扩容" },
    @{ id="awsnetwork12721"; src="https://aws.amazon.com/message/12721/"; sym="internal network connection surge congestion"; key="capacity automation triggered client retry storm"; pa="an automated scale event caused clients to open far more connections than usual"; pb="the link between the internal and main networks stayed congested as retries compounded"; se="自动扩容触发大量客户端连接，内外网设备被重试风暴打满"; rc="An automated capacity change triggered a large connection surge from clients, overwhelming the devices between the internal and main AWS networks; retries kept the congestion high. 中文根因：自动扩容引发连接风暴和重试，内外网链路持续拥塞"; fix="限制客户端重试并恢复网络容量" },
    @{ id="awssimpledb"; src="https://aws.amazon.com/message/65649/"; sym="simpledb storage nodes handshake timeout"; key="lock service deregistered nodes too fast"; pa="several storage nodes lost power and the lock service removed them at once"; pb="healthy nodes then missed an aggressive handshake deadline and could not rejoin"; se="多台存储节点断电后被锁服务快速摘除，健康节点也握手超时无法回集群"; rc="Multiple SimpleDB storage nodes lost power; the lock service removed them quickly, handshake latency exceeded an aggressive timeout, and healthy metadata nodes also left and could not rejoin. 中文根因：存储节点断电后握手超时扩散，健康节点也退出集群"; fix="提高握手超时并重启元数据节点" },
    @{ id="awsdx17908"; src="https://aws.amazon.com/message/17908/"; sym="direct connect latent os defect"; key="failover optimization protocol bad packet signature"; pa="a new failover protocol hit a hidden operating system defect when a customer sent a specific packet pattern"; pb="devices failed repeatedly until the protocol was disabled and tokyo connectivity returned"; se="新故障切换协议被特定流量触发隐藏缺陷，东京 Direct Connect 设备反复失效"; rc="A new failover-optimization protocol hit a latent operating system defect when a customer traffic pattern matched a specific packet signature; devices failed until the protocol was disabled. 中文根因：新故障切换协议触发系统隐藏缺陷，东京 Direct Connect 设备失效"; fix="禁用新协议并逐台恢复设备" }
)

if ($incidents.Count -ne 30) { throw "expected 30 incidents, got $($incidents.Count)" }

$rows = New-Object System.Collections.ArrayList
$n = 0
function Store-Case([string]$q, [string]$rc, [string]$fix, [string]$src) {
    $script:n++
    $log = Join-Path $env:TEMP ("scx-confirm2-{0:D3}-{1}.log" -f $script:n, [guid]::NewGuid().ToString("N"))
    $text = ("{0}`n公开复盘, 来源: {1}`n根因: {2}" -f $q, $src, $rc)
    Write-Utf8 $log $text
    $prev = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    try { $out = (& $Binary --query $q --store 1 --fix $fix --mem-dir $MemDir $log 2>&1 | Out-String) }
    finally { $ErrorActionPreference = $prev }
    if ($out -notmatch "stored case=([^\s]+) added=yes") { throw "store failed case $($script:n): $q`n$out" }
    return $Matches[1]
}

foreach ($c in $incidents) {
    $id = Store-Case $c.sym $c.rc $c.fix $c.src
    $h = $id.Split('_')[-1]
    $note = "target=$h source=$c.src"
    foreach ($q in @(
        @{ q=$c.sym; layer="literal" },
        @{ q=$c.key; layer="literal" },
        @{ q=$c.pa;  layer="paraphrase" },
        @{ q=$c.pb;  layer="paraphrase" },
        @{ q=$c.se;  layer="semantic" }
    )) {
        [void]$rows.Add([pscustomobject]@{ query=$q.q; layer=$q.layer; case_id=$id; note=$note })
    }
}

$lines = @("query,layer,case_id,note")
foreach ($r in $rows) {
    $lines += ((@($r.query, $r.layer, $r.case_id, $r.note) | ForEach-Object { CsvField ([string]$_) }) -join ",")
}
Write-Utf8 $Csv ($lines -join "`n")

$l = @($rows | Where-Object { $_.layer -eq "literal" }).Count
$p = @($rows | Where-Object { $_.layer -eq "paraphrase" }).Count
$s = @($rows | Where-Object { $_.layer -eq "semantic" }).Count
Write-Host ("confirm2 corpus: cases={0} eval={1} literal={2} paraphrase={3} semantic={4}" -f $incidents.Count, $rows.Count, $l, $p, $s)
Write-Host "next: powershell -File scripts\holdout-build.ps1 -Csv eval-real\confirm2-cases.csv -Out eval-real\confirm2-baseline.json -JudgeBy mechanical-target-confirm2-v1 -JudgeDate 2026-10-23T00:00:00Z"
